package com.projecthero.mod.hero.power.p22;

import com.projecthero.mod.ProjectHeroMod;

import net.fabricmc.fabric.api.particle.v1.FabricParticleTypes;

import net.minecraft.core.Registry;
import net.minecraft.core.particles.SimpleParticleType;
import net.minecraft.core.registries.BuiltInRegistries;

/**
 * v0.17.1 Chlorokinesis revamp: the power's own particles (client factories in
 * {@code client.mutation.chloro.ChloroParticleClient}, sprites generated by
 * {@code scratchpad/chlorokinesis_v0171/gen_chloro_v0171.js}):
 * <ul>
 * <li>{@link #LEAF} -- a leaf that sways, spins and drifts down (Verdant Form, the glide canopy, Overgrowth);</li>
 * <li>{@link #PETAL} -- a pink / white petal that flutters (Bloom Burst, the Treant's crown);</li>
 * <li>{@link #SPORE} -- a glowing yellow-green mote that hangs in the air (Spore Cloud);</li>
 * <li>{@link #SAP} -- a full-bright drop of green sap (Root Sense trails, the vines, the roots).</li>
 * </ul>
 */
public final class ChloroParticles {
	public static final SimpleParticleType LEAF = FabricParticleTypes.simple(false);
	public static final SimpleParticleType PETAL = FabricParticleTypes.simple(false);
	public static final SimpleParticleType SPORE = FabricParticleTypes.simple(false);
	public static final SimpleParticleType SAP = FabricParticleTypes.simple(true);

	private static boolean registered;

	private ChloroParticles() {
	}

	/** From {@code RevampBatchE.init}. */
	public static void register() {
		if (registered) {
			return;
		}
		registered = true;
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("chloro_leaf"), LEAF);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("chloro_petal"), PETAL);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("chloro_spore"), SPORE);
		Registry.register(BuiltInRegistries.PARTICLE_TYPE, ProjectHeroMod.id("chloro_sap"), SAP);
	}
}
